"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { sendChatMessage } from "@/lib/api/ai";
import { LibrelloIcon } from "@/components/modules/shared/LibrelloLogo";

export default function BiblioBot() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [providerBadge, setProviderBadge] = useState("Librello AI");
  const [messages, setMessages] = useState([
    {
      id: "welcome-msg",
      sender: "bot",
      text: "Greetings. I am your Librello Concierge, dedicated to assisting your archival inquiries, literary discovery, and circulation requests. How may I be of service?",
      time: "Just now",
    },
  ]);

  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, isOpen, loading]);

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => inputRef.current?.focus(), 150);
    }
  }, [isOpen]);

  const quickPrompts = [
    {
      label: "Circulation Process",
      prompt: "How does physical book circulation and delivery work?",
    },
    {
      label: "Reading Selections",
      prompt: "Can you recommend celebrated fiction or philosophy editions?",
    },
    {
      label: "Archival Care & Return",
      prompt: "What are the book care and return period guidelines?",
    },
    {
      label: "Membership Fees",
      prompt: "How are borrowing fees and payments handled?",
    },
  ];

  const handleSendMessage = async (textToSend?: string) => {
    const query = textToSend || input;
    if (!query.trim() || loading) return;

    const userMessage = {
      id: `user-${Date.now()}`,
      sender: "user",
      text: query.trim(),
      time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    try {
      const history = messages
        .filter((m) => m.id !== "welcome-msg")
        .map((m) => ({
          sender: m.sender,
          text: m.text,
        }));

      const res = await sendChatMessage(query, history);

      if (res.provider) {
        setProviderBadge(res.provider);
      }

      const botMessage = {
        id: `bot-${Date.now()}`,
        sender: "bot",
        text: res.reply,
        provider: res.provider,
        time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
      };

      setMessages((prev) => [...prev, botMessage]);
    } catch (error) {
      const errorMessage = {
        id: `err-${Date.now()}`,
        sender: "bot",
        text: "The concierge network experienced an interruption. Please inquire again momentarily.",
        time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setLoading(false);
    }
  };

  const handleClearChat = () => {
    setMessages([
      {
        id: "welcome-msg",
        sender: "bot",
        text: "Conversation reset. How may I assist your literary research today?",
        time: "Just now",
      },
    ]);
  };

  const renderFormattedText = (text) => {
    const lines = text.split("\n");
    return lines.map((line, idx) => {
      const parts = line.split(/(\*\*.*?\*\*)/g);
      return (
        <div
          key={idx}
          className={
            line.startsWith("- ")
              ? "ml-3 flex items-start gap-1.5 my-1"
              : "my-0.5"
          }
        >
          {line.startsWith("- ") && (
            <span className="text-primary font-bold">•</span>
          )}
          <span>
            {parts.map((p, pIdx) => {
              if (p.startsWith("**") && p.endsWith("**")) {
                return (
                  <strong key={pIdx} className="font-semibold text-foreground">
                    {p.slice(2, -2)}
                  </strong>
                );
              }
              return line.startsWith("- ") ? p.replace(/^- /, "") : p;
            })}
          </span>
        </div>
      );
    });
  };

  return (
    <>
      {/* Floating Toggle Button */}
      <div className="fixed bottom-6 right-6 z-50 select-none">
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Open Librello Concierge"
          title="Librello Concierge"
          className="w-13 h-13 rounded-full bg-primary text-white flex items-center justify-center shadow-lg border border-primary/40 cursor-pointer"
        >
          {isOpen ? (
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          ) : (
            <LibrelloIcon size={24} className="text-white" />
          )}
        </motion.button>
      </div>

      {/* Expandable Chat Drawer */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 15, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 15, scale: 0.98 }}
            transition={{ duration: 0.2 }}
            className="fixed bottom-22 right-4 sm:right-6 z-50 w-[92vw] sm:w-[390px] h-[540px] max-h-[80vh] rounded-xl border border-border bg-card shadow-2xl flex flex-col overflow-hidden select-text text-foreground"
          >
            {/* Concierge Header */}
            <div className="px-4 py-3 border-b border-border bg-card-soft flex items-center justify-between shrink-0">
              <div className="flex items-center gap-2.5">
                <LibrelloIcon size={28} className="text-foreground" />
                <div>
                  <h3 className="text-sm font-serif font-semibold text-foreground leading-tight">
                    Librello Concierge
                  </h3>
                  <p className="text-[10px] text-muted-foreground uppercase tracking-wider">
                    Literary Advisor ({providerBadge})
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={handleClearChat}
                  title="Reset conversation"
                  className="p-1.5 rounded text-muted-foreground hover:text-foreground hover:bg-card transition-colors cursor-pointer"
                >
                  <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <polyline points="3 6 5 6 21 6" />
                    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                  </svg>
                </button>
                <button
                  type="button"
                  onClick={() => setIsOpen(false)}
                  title="Minimize"
                  className="p-1.5 rounded text-muted-foreground hover:text-foreground hover:bg-card transition-colors cursor-pointer"
                >
                  <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <line x1="4" y1="12" x2="20" y2="12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Messages Area */}
            <div className="flex-1 min-h-0 p-4 overflow-y-auto space-y-3 text-xs leading-relaxed">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${
                    msg.sender === "user" ? "justify-end" : "justify-start"
                  }`}
                >
                  <div
                    className={`max-w-[84%] px-3.5 py-2.5 rounded-lg text-xs leading-relaxed ${
                      msg.sender === "user"
                        ? "bg-primary text-white"
                        : "bg-card-soft border border-border text-foreground"
                    }`}
                  >
                    {renderFormattedText(msg.text)}
                  </div>
                </div>
              ))}

              {loading && (
                <div className="flex justify-start">
                  <div className="px-3.5 py-2 rounded-lg bg-card-soft border border-border text-muted-foreground text-xs italic">
                    Consulting archive index...
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Quick Prompts */}
            <div className="px-3 py-2 border-t border-border/70 bg-card-soft/50 flex flex-wrap gap-1.5 shrink-0">
              {quickPrompts.map((item, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => handleSendMessage(item.prompt)}
                  className="px-2 py-1 rounded text-[10px] font-medium border border-border bg-card text-muted-foreground hover:text-foreground hover:border-primary/40 transition-colors cursor-pointer"
                >
                  {item.label}
                </button>
              ))}
            </div>

            {/* Input Form */}
            <form
              onSubmit={(e) => {
                e.preventDefault();
                handleSendMessage();
              }}
              className="p-3 border-t border-border bg-card flex items-center gap-2 shrink-0"
            >
              <input
                ref={inputRef}
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask your literary concierge..."
                className="input-field !h-9 !text-xs !rounded-md flex-1"
                disabled={loading}
              />
              <button
                type="submit"
                disabled={loading || !input.trim()}
                className="btn-primary !h-9 !px-3 !py-1 text-xs !rounded-md disabled:opacity-40"
              >
                Send
              </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
